text:
{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the liquid look like at the intended measurement point?"
    },
    {
      "question_id": "q2",
      "question": "Which industry or application area is this liquid process used in?"
    },
    {
      "question_id": "q3",
      "question": "Is the measurement intended for research, a pilot line or production?"
    },
    {
      "question_id": "q4",
      "question": "Is there a reference method that provides comparison values for the liquid?"
    },
    {
      "question_id": "q5",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q6",
      "question": "Once the target variable is defined, over what range must it be monitored?"
    }
  ],
  "plan": {
    "objective": "Test whether spectral differences between good and off-specification samples can be linked to a defined quality variable.",
    "samples_and_states": [
      {
        "text": "Collect representative retained good and off-specification samples covering the relevant process states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Link each sample to its documented specification status and, once the target is defined, independent reference values.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Record MIR, NIR and Raman spectra from the same retained samples under documented measurement conditions.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare the screening methods against documented sample status and any established target reference values.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate any resulting relationship to the defined target on independent material excluded from screening and model development.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Defer method and sensor selection unless a target is defined and independent validation meets criteria agreed with you before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Do not treat screening separation alone as proof of contaminant identity or in-line performance.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify appearance, application, intended use, references, criteria and target range.",
      "Collect representative retained good and off-specification samples.",
      "Establish sample status and independent target reference values.",
      "Record and compare spectra under documented conditions.",
      "Validate on independent material against pre-agreed criteria.",
      "Proceed or stop according to validation and target definition."
    ]
  },
  "decision_basis": [
    {
      "text": "Base any later method and sensor selection on comparison against independent reference values on independent material, using criteria agreed with you before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
